-- MVP-015 / D064: buyer creates a private round from trusted structured
-- materials. PostgreSQL17 CI ONLY; not a migration nor installed in DEV.
-- No supplier invitation or WhatsApp is generated by this function.
-- Rounds start PROGRAMADA until geographic/catalog distribution is real.
create role cotironda_buyer_writer_d064 nologin noinherit nobypassrls;
grant usage on schema public,cotironda_private to cotironda_buyer_writer_d064;
grant execute on function cotironda_private.buyer_round_overview_v1(uuid),
 cotironda_private.request_user_id_v035() to cotironda_buyer_writer_d064;
grant select on public.organizations,public.organization_members
 to cotironda_buyer_writer_d064;
create policy d064_writer_members on public.organization_members
 for select to cotironda_buyer_writer_d064
 using(user_id=(select cotironda_private.request_user_id_v035()));
create policy d064_writer_org on public.organizations
 for select to cotironda_buyer_writer_d064
 using(organization_type in('buyer','both') and exists(
  select 1 from public.organization_members m
  where m.organization_id=organizations.id and m.status='active'
   and m.user_id=(select cotironda_private.request_user_id_v035())
   and m.membership_role in('owner','manager')
 ));

grant select,insert,update(status,opened_at,closed_at) on
 cotironda_private.rounds_v1 to cotironda_buyer_writer_d064;
grant select,insert on cotironda_private.round_items_v1
 to cotironda_buyer_writer_d064;
create policy d064_writer_round_select on cotironda_private.rounds_v1
 for select to cotironda_buyer_writer_d064
 using(exists(select 1 from public.organizations o
  where o.id=rounds_v1.buyer_org_id));
create policy d064_writer_round_insert on cotironda_private.rounds_v1
 for insert to cotironda_buyer_writer_d064
 with check(exists(select 1 from public.organizations o
  where o.id=rounds_v1.buyer_org_id));
create policy d064_writer_round_update on cotironda_private.rounds_v1
 for update to cotironda_buyer_writer_d064
 using(exists(select 1 from public.organizations o
  where o.id=rounds_v1.buyer_org_id))
 with check(exists(select 1 from public.organizations o
  where o.id=rounds_v1.buyer_org_id));
create policy d064_writer_item_select on cotironda_private.round_items_v1
 for select to cotironda_buyer_writer_d064
 using(exists(select 1 from cotironda_private.rounds_v1 r where r.id=round_id));
create policy d064_writer_item_insert on cotironda_private.round_items_v1
 for insert to cotironda_buyer_writer_d064
 with check(exists(select 1 from cotironda_private.rounds_v1 r where r.id=round_id));

create table cotironda_private.round_requests_d064(
 round_id uuid primary key references cotironda_private.rounds_v1(id) on delete restrict,
 buyer_org_id uuid not null references public.organizations(id) on delete restrict,
 created_by uuid not null references auth.users(id) on delete restrict,
 request_key uuid not null,
 content_sha256 text not null check(content_sha256 ~ '^[0-9a-f]{64}$'),
 delivery_zone text not null check(char_length(delivery_zone) between 3 and 65),
 buyer_iva_request text not null check(buyer_iva_request in
  ('no_especificado','con_iva','sin_iva','contradictorio')),
 created_at timestamptz not null default pg_catalog.clock_timestamp(),
 unique(buyer_org_id,created_by,request_key)
);
alter table cotironda_private.round_requests_d064 enable row level security;
revoke all on cotironda_private.round_requests_d064
 from public,anon,authenticated,service_role,cotironda_app;
grant select,insert on cotironda_private.round_requests_d064
 to cotironda_buyer_writer_d064;
create policy d064_request_select on cotironda_private.round_requests_d064
 for select to cotironda_buyer_writer_d064
 using(exists(select 1 from public.organizations o
   where o.id=buyer_org_id));
create policy d064_request_insert on cotironda_private.round_requests_d064
 for insert to cotironda_buyer_writer_d064
 with check(exists(select 1 from public.organizations o
   where o.id=buyer_org_id));
create trigger d064_requests_immutable before update or delete
 on cotironda_private.round_requests_d064
 for each row execute function cotironda_private.reject_immutable_quote_v1();

create function cotironda_private.create_buyer_round_d064(
 p_buyer uuid,p_key uuid,p_zone text,p_iva text,p_items jsonb
) returns jsonb
language plpgsql volatile security definer set search_path='' as $fn$
declare
 v_uid uuid;v_line jsonb;v_items jsonb;
 v_zone text;v_hash text;v_previous cotironda_private.round_requests_d064%rowtype;
 v_round uuid;v_now timestamptz:=pg_catalog.clock_timestamp();
 v_number integer;v_count integer;
 v_product text;v_qty text;v_unit text;
begin
 -- D025 checks JWT role, email verification, anon flag and live auth.sessions.
 -- It is NOT a permission check for a specific org; performed below.
 perform 1 from cotironda_private.buyer_round_overview_v1(
   '00000000-0000-4000-8000-000000000064'::uuid);
 v_uid:=cotironda_private.request_user_id_v035();
 if p_buyer is null or p_key is null
 or p_zone is null or pg_catalog.length(pg_catalog.btrim(p_zone))<3
 or pg_catalog.length(pg_catalog.btrim(p_zone))>65
 or pg_catalog.btrim(p_zone) !~ '^[[:alnum:] .,-]+$'
 or p_iva is null or p_iva not in
    ('no_especificado','con_iva','sin_iva','contradictorio')
 or pg_catalog.jsonb_typeof(p_items) is distinct from 'array'
 or pg_catalog.jsonb_array_length(p_items)<1
 or pg_catalog.jsonb_array_length(p_items)>8
 then raise exception 'd064_invalid_request' using errcode='22023';end if;
 if not exists(select 1 from public.organizations o
  join public.organization_members m on m.organization_id=o.id
  where o.id=p_buyer and o.organization_type in('buyer','both')
   and m.user_id=v_uid and m.status='active'
   and m.membership_role in('owner','manager'))
 then raise exception 'd064_buyer_not_authorized' using errcode='42501';end if;
 v_count:=pg_catalog.jsonb_array_length(p_items);
 for v_number in 0..v_count-1 loop
  v_line:=p_items->v_number;
  if pg_catalog.jsonb_typeof(v_line) is distinct from 'object'
   or (select count(*) from pg_catalog.jsonb_object_keys(v_line))<>4
   or not (v_line ?& array['line_no','product_code','quantity','unit'])
   or pg_catalog.jsonb_typeof(v_line->'line_no') is distinct from 'number'
   or v_line->>'line_no' is distinct from (v_number+1)::text
   or pg_catalog.jsonb_typeof(v_line->'product_code') is distinct from 'string'
   or (v_line->>'product_code') !~ '^[a-z][a-z0-9_]{2,49}$'
   or pg_catalog.jsonb_typeof(v_line->'quantity') is distinct from 'string'
   or (v_line->>'quantity') !~ '^[1-9][0-9]{0,8}(\.[0-9]{1,3})?$'
   or pg_catalog.jsonb_typeof(v_line->'unit') is distinct from 'string'
   or v_line->>'unit' not in ('unit','bag','box','kg','g','l','ml',
                              'm','m2','m3','roll','pack')
  then raise exception 'd064_invalid_line' using errcode='22023';end if;
  if exists(select 1 from pg_catalog.jsonb_array_elements(p_items) x(value)
     where x.value->>'product_code'=v_line->>'product_code'
     having count(*)>1)
  then raise exception 'd064_duplicate_product' using errcode='22023';end if;
 end loop;
 v_zone:=pg_catalog.btrim(p_zone);
 v_hash:=pg_catalog.encode(pg_catalog.sha256(pg_catalog.convert_to(
  pg_catalog.jsonb_build_object('org',p_buyer,'zone',v_zone,'iva',p_iva,
    'items',p_items)::text,'UTF8')),'hex');
 -- Secure and deterministic serialization of double clicks and concurrent
 -- requests from the SAME buyer+idempotency key. No orphan round on replay.
 perform pg_catalog.pg_advisory_xact_lock(
  pg_catalog.hashtextextended(p_buyer::text||':'||v_uid::text||':'||p_key::text,0));
 select * into v_previous from cotironda_private.round_requests_d064
  where buyer_org_id=p_buyer and created_by=v_uid and request_key=p_key;
 if found then
  if v_previous.content_sha256<>v_hash then
   raise exception 'd064_request_conflict' using errcode='23505';end if;
  return pg_catalog.jsonb_build_object('roundId',v_previous.round_id,
   'status','programada','repeated',true);
 end if;
 -- The buyer does NOT select supplier IDs or request sending: no invitations
 -- are manufactured. A separate vetted geographic matcher will distribute.
 insert into cotironda_private.rounds_v1(buyer_org_id,begins_at,ends_at)
  values(p_buyer,v_now+interval '30 seconds',v_now+interval '2 days')
  returning id into v_round;
 for v_number in 0..v_count-1 loop
  v_line:=p_items->v_number;
  insert into cotironda_private.round_items_v1
    (round_id,line_no,product_code,quantity,unit)
   values(v_round,(v_line->>'line_no')::smallint,
    v_line->>'product_code',(v_line->>'quantity')::numeric(18,3),
    v_line->>'unit');
 end loop;
 insert into cotironda_private.round_requests_d064
  (round_id,buyer_org_id,created_by,request_key,content_sha256,
   delivery_zone,buyer_iva_request)
  values(v_round,p_buyer,v_uid,p_key,v_hash,v_zone,p_iva);
 return pg_catalog.jsonb_build_object('roundId',v_round,
  'status','programada','repeated',false);
end;$fn$;
grant create on schema cotironda_private to cotironda_buyer_writer_d064;
grant cotironda_buyer_writer_d064 to postgres with set true,inherit false;
alter function cotironda_private.create_buyer_round_d064(
 uuid,uuid,text,text,jsonb) owner to cotironda_buyer_writer_d064;
revoke cotironda_buyer_writer_d064 from postgres;
revoke create on schema cotironda_private from cotironda_buyer_writer_d064;
revoke all on function cotironda_private.create_buyer_round_d064(
 uuid,uuid,text,text,jsonb) from public,anon,authenticated,service_role,cotironda_app;
grant execute on function cotironda_private.create_buyer_round_d064(
 uuid,uuid,text,text,jsonb) to authenticated;
create function public.create_buyer_round_d064(
 p_buyer uuid,p_key uuid,p_zone text,p_iva text,p_items jsonb
) returns jsonb
language sql volatile security invoker set search_path='' as $fn$
 select cotironda_private.create_buyer_round_d064(
 p_buyer,p_key,p_zone,p_iva,p_items);
$fn$;
revoke all on function public.create_buyer_round_d064(uuid,uuid,text,text,jsonb)
 from public,anon,authenticated,service_role,cotironda_app;
grant execute on function public.create_buyer_round_d064(uuid,uuid,text,text,jsonb)
 to authenticated;
comment on function public.create_buyer_round_d064(uuid,uuid,text,text,jsonb)
 is 'MVP-015: only verified buyer manager; exact structured items+delivery zone; no supplier invitation or extra confirmation';
